fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    // The separator is guaranteed to be non-empty.
    // We implement the behavior like str::rsplitn with maxsplit+1 parts:
    // - If maxsplit == 0, no splitting, return vec with original string only.
    // - Otherwise, split from the right up to maxsplit times.

    // maxsplit is u8, convert to usize for use in Rust string splitting.
    let maxsplit = maxsplit as usize;

    a.into_iter()
        .map(|s| {
            if maxsplit == 0 {
                // No splitting, result is a vec with the original string only.
                vec![s]
            } else {
                // If input string is empty, the split result should be a single empty string.
                if s.is_empty() {
                    vec![String::new()]
                } else {
                    // Use rsplitn for splitting from the right up to maxsplit times,
                    // which produces at most maxsplit + 1 parts.
                    // Collect into Vec<String>.
                    s.rsplitn(maxsplit + 1, &sep)
                        .map(|part| part.to_string())
                        .collect::<Vec<String>>()
                        // rsplitn produces parts starting from right, so reverse to keep original left-to-right order:
                        .into_iter()
                        .rev()
                        .collect()
                }
            }
        })
        .collect()
}